1	//! Shared test helpers.
2	
3	use mtg_engine::actions::{Action, Target};
4	use mtg_engine::cards::CardRegistry;
5	use mtg_engine::ids::{CardId, ObjectId, PlayerId};
6	use mtg_engine::state::GameState;
7	use mtg_engine::types::*;
8	
9	pub const P0: PlayerId = PlayerId(0);
10	pub const P1: PlayerId = PlayerId(1);
11	
12	/// Set up a game state at a specific step with the given player as active and having priority.
13	pub fn game_at_step(step: Step, active: PlayerId) -> GameState {
14	    let mut state = GameState::new(2);
15	    state.step = step;
16	    state.active_player = active;
17	    state.priority_player = Some(active);
18	    state.is_first_turn = false;
19	    state.players[0].life = 20;
20	    state.players[1].life = 20;
21	    state
22	}
23	
24	/// Place a creature on the battlefield that is ready to act (no summoning sickness).
25	pub fn ready_creature(state: &mut GameState, owner: PlayerId, power: i32, toughness: i32) -> ObjectId {
26	    let id = state.create_object(CardId(9999), owner, Zone::Battlefield, Some(power), Some(toughness));
27	    state.get_object_mut(id).unwrap().summoning_sick = false;
28	    id
29	}
30	
31	/// Place a creature on the battlefield with summoning sickness.
32	pub fn sick_creature(state: &mut GameState, owner: PlayerId, power: i32, toughness: i32) -> ObjectId {
33	    state.create_object(CardId(9999), owner, Zone::Battlefield, Some(power), Some(toughness))
34	}
35	
36	/// Put a named card into a player's hand. Returns the object ID.
37	pub fn spell_in_hand(state: &mut GameState, registry: &CardRegistry, name: &str, player: PlayerId) -> ObjectId {
38	    let card_id = registry.get_id_by_name(name)
39	        .unwrap_or_else(|| panic!("Unknown card: {}", name));
40	    let data = registry.card_data(card_id);
41	    let power = data.as_ref().and_then(|d| d.power);
42	    let toughness = data.as_ref().and_then(|d| d.toughness);
43	    let id = state.create_object(card_id, player, Zone::Hand, power, toughness);
44	    state.get_object_mut(id).unwrap().name = name.into();
45	    id
46	}
47	
48	/// Add exactly enough mana to a player's pool to pay for a card by name.
49	pub fn add_mana_for(state: &mut GameState, registry: &CardRegistry, name: &str, player: PlayerId) {
50	    let card_id = registry.get_id_by_name(name)
51	        .unwrap_or_else(|| panic!("Unknown card: {}", name));
52	    let data = registry.card_data(card_id)
53	        .unwrap_or_else(|| panic!("No card data for: {}", name));
54	    if let Some(ref cost) = data.cost {
55	        for sym in &cost.symbols {
56	            match sym {
57	                ManaSymbol::Colored(c) => {
58	                    let mana_type = match c {
59	                        Color::White => ManaType::White,
60	                        Color::Blue => ManaType::Blue,
61	                        Color::Black => ManaType::Black,
62	                        Color::Red => ManaType::Red,
63	                        Color::Green => ManaType::Green,
64	                    };
65	                    state.get_player_mut(player).mana_pool.add(mana_type, 1);
66	                }
67	                ManaSymbol::Generic(n) => {
68	                    state.get_player_mut(player).mana_pool.add(ManaType::Colorless, *n);
69	                }
70	                _ => {}
71	            }
72	        }
73	    }
74	}
75	
76	/// Put a named card in hand and add mana to cast it. Returns the object ID.
77	pub fn castable_spell(state: &mut GameState, registry: &CardRegistry, name: &str, player: PlayerId) -> ObjectId {
78	    let id = spell_in_hand(state, registry, name, player);
79	    add_mana_for(state, registry, name, player);
80	    id
81	}
82	
83	/// Cast a spell targeting something, then resolve the top of the stack.
84	/// Returns the new state after resolution.
85	pub fn cast_and_resolve(
86	    state: &GameState,
87	    registry: &CardRegistry,
88	    spell_id: ObjectId,
89	    targets: Vec<Target>,
90	) -> GameState {
91	    let mut new_state = mtg_engine::engine::submit_action(
92	        state,
93	        &Action::CastSpell { object_id: spell_id, targets, sacrifice: None, exile_count: None, alternative_cost: None },
94	        registry,
95	    );
96	    mtg_engine::stack::resolve_top_of_stack(&mut new_state, registry);
97	    new_state
98	}
99	
100	/// Place a named card on the battlefield, ready to act. Returns the object ID.
101	pub fn named_creature(
102	    state: &mut GameState,
103	    registry: &CardRegistry,
104	    name: &str,
105	    owner: PlayerId,
106	) -> ObjectId {
107	    let card_id = registry.get_id_by_name(name)
108	        .unwrap_or_else(|| panic!("Unknown card: {}", name));
109	    let data = registry.card_data(card_id)
110	        .unwrap_or_else(|| panic!("No card data for: {}", name));
111	    let id = state.create_object(card_id, owner, Zone::Battlefield, data.power, data.toughness);
112	    let obj = state.get_object_mut(id).unwrap();
113	    obj.name = name.into();
114	    obj.summoning_sick = false;
115	    id
116	}
117	
118	/// Place a named equipment card on the battlefield (unattached). Returns the object ID.
119	pub fn named_equipment(
120	    state: &mut GameState,
121	    registry: &CardRegistry,
122	    name: &str,
123	    owner: PlayerId,
124	) -> ObjectId {
125	    let id = named_creature(state, registry, name, owner);
126	    let obj = state.get_object_mut(id).unwrap();
127	    obj.is_equipment = true;
128	    id
129	}
